B.ai8=new A.Pl("api-chat",B.mC,"Fast & Deep Research Chat (SSE)","POST","/api/chat","Streams hybrid GraphRAG responses over Server-Sent Events with inline citation chips, retrieval tool events, and optional Skeptic verification.",B.a5,B.cp3,"EXAMPLE REQUEST (CURL)",'curl -N -X POST http://localhost:8000/api/chat \\\n  -H "Content-Type: application/json" \\\n  -d \'{"message": "Who calls verify_jwt?", "mode": "deep"}\'',"SSE STREAM EVENTS",'event: tool_event\ndata: {"tool": "mcp_merge_rank", "status": "done"}\n\nevent: token\ndata: {"text": "verify_jwt is called by login_handler [1]"}\n\ndata: {"grounding_verified": true, "unsupported_claims": 0}')
